using NovaHarvest.Core.World;
namespace NovaHarvest.Core.Player; public sealed class PlayerController { public PlayerPosition Position { get; } public PlayerState State { get; } public PlayerController(int startX = 5, int startY = 5) { Position = new PlayerPosition(startX, startY); State = new PlayerState(); } public bool Move(int dx, int dy) { if (!State.IsAlive) return false; Position.Move(dx, dy); return true; } public IReadOnlyList<WorldObject> GetNearbyObjects(WorldManager world, int radius = 1) => world.GetNearby(Position.X, Position.Y, radius); }
